          </p>
        )}
      </div>

      <div className="flex gap-3 items-center">
        <Avatar className="h-9 w-9 border border-zinc-200 hidden sm:block">
          <AvatarFallback className="bg-zinc-900 text-white text-xs font-bold">
            ME
