                                "text-[9px] font-bold uppercase tracking-widest border-zinc-200",
                                isPaused
                                  ? "bg-zinc-100 text-zinc-500"
                                  : "bg-zinc-900 text-white border-zinc-900",
                              )}
                            >
                              {pledge.recipientCategory}
                            </Badge>
                            <h3
                              className={cn(
                                "text-lg font-bold leading-tight uppercase tracking-tight",
                                isPaused ? "text-zinc-500" : "text-zinc-900",
                              )}
                            >
                              {pledge.recipientName}
                            </h3>
                          </div>
                        </div>

                        {/* Three Dots Menu - Lifecycle Actions */}
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 text-zinc-400 hover:text-zinc-900 -mr-2"
                            >
                              <MoreHorizontal className="h-5 w-5" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-48">
                            {pledge.status === "Active" ? (
                              <DropdownMenuItem
                                onClick={() => {
                                  handleEditClick(pledge);
                                  setIsPauseOpen(true);
                                }}
                                className="text-[10px] font-bold uppercase tracking-widest"
                              >
                                <PauseCircle className="mr-2 h-4 w-4" /> Pause
                                Pledge
                              </DropdownMenuItem>
                            ) : (
                              <DropdownMenuItem
                                onClick={() => handleResumePledge(pledge.id)}
                                className="text-emerald-600 text-[10px] font-bold uppercase tracking-widest"
                              >
                                <PlayCircle className="mr-2 h-4 w-4" /> Resume
                                Pledge
                              </DropdownMenuItem>
                            )}
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              className="text-red-600 text-[10px] font-bold uppercase tracking-widest"
                              onClick={() => handleStopPledge(pledge.id)}
                            >
                              <X className="mr-2 h-4 w-4" /> Cancel Pledge
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>

                      {/* Body: Amount & Controls */}
                      <div className="flex items-end justify-between mb-6">
                        <div>
                          <div
                            className={cn(
                              "text-3xl font-bold tabular-nums tracking-tighter",
                              isPaused ? "text-zinc-400" : "text-zinc-900",
                            )}
                          >
                            {formatCurrency(pledge.amount)}
                          </div>
                          <div className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em] mt-1">
                            {pledge.frequency}
                          </div>
                        </div>

                        {/* Main Edit Button */}
                        {isPaused ? (
                          <Button
                            onClick={() => handleResumePledge(pledge.id)}
                            className="bg-emerald-600 hover:bg-emerald-700 text-white shadow-md gap-2 font-bold uppercase tracking-widest text-[10px]"
                          >
                            <PlayCircle className="h-4 w-4" /> Resume Now
                          </Button>
                        ) : (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleEditClick(pledge)}
                            className="border-zinc-200 text-zinc-700 hover:text-zinc-900 hover:border-zinc-300 gap-2 bg-white shadow-sm font-bold uppercase tracking-widest text-[9px] h-8 rounded-lg"
                          >
                            <Edit2 className="h-3.5 w-3.5" /> Edit Details
                          </Button>
                        )}
                      </div>

                      <Separator className="mb-4" />

                      {/* Footer: Payment & Dates */}
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 text-sm">
                        {/* Payment Method with Swap */}
                        {method && (
                          <div className="flex items-center gap-3">
                            <div
                              className={cn(
                                "p-1.5 rounded border shadow-sm",
                                isPaused
                                  ? "bg-zinc-50 border-zinc-200 text-zinc-400"
                                  : "bg-white border-zinc-200 text-zinc-700",
                              )}
                            >
                              {method.type === "card" ? (
                                <CreditCard className="h-4 w-4" />
                              ) : (
                                <Wallet className="h-4 w-4" />
                              )}
                            </div>
                            <div className="flex flex-col">
                              <span
                                className={cn(
                                  "text-[10px] font-bold uppercase tracking-tight",
                                  isPaused ? "text-zinc-400" : "text-zinc-700",
                                )}
                              >
                                {method.brand} ••{method.last4}
                              </span>
                              <button
                                onClick={() => handleOpenMove(pledge)}
                                className="text-[9px] font-black text-zinc-400 hover:text-zinc-900 uppercase tracking-widest text-left flex items-center gap-1 mt-0.5"
                              >
                                Change{" "}
                                <ArrowRightLeft className="h-2.5 w-2.5" />
                              </button>
                            </div>
                          </div>
                        )}

                        {/* Date Info */}
                        <div className="flex items-center gap-2 text-zinc-500 bg-zinc-50 px-3 py-1.5 rounded-full border border-zinc-100 self-start sm:self-auto">
                          {isPaused ? (
                            <>
                              <PauseCircle className="h-3.5 w-3.5 text-amber-500" />
                              <span className="text-[10px] font-bold uppercase tracking-widest">
                                Paused until{" "}
                                {format(new Date(pledge.pausedUntil!), "MMM d")}
                              </span>
                            </>
                          ) : (
                            <>
                              <Clock className="h-3.5 w-3.5 text-emerald-500" />
                              <span className="text-[10px] font-bold uppercase tracking-widest">
                                Next:{" "}
                                {format(
                                  new Date(pledge.nextChargeDate),
                                  "MMM d, yyyy",
                                )}
                              </span>
                            </>
                          )}
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>

      {/* --- EDIT PLEDGE DIALOG --- */}
      <Dialog
        open={!!editingPledge}
        onOpenChange={(open) => !open && setEditingPledge(null)}
      >
        <DialogContent className="sm:max-w-[500px] p-0 gap-0 overflow-hidden shadow-2xl border-none rounded-2xl">
          <div className="bg-zinc-900 p-6 text-white relative overflow-hidden text-left">
            <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none text-white">
              <ShieldCheck className="h-32 w-32 -rotate-12" />
            </div>
            <div className="relative z-10 flex gap-4 items-center">
              <Avatar className="h-16 w-16 border-2 border-white/20 shadow-lg">
                <AvatarImage src={editingPledge?.recipientAvatar} />
                <AvatarFallback>GH</AvatarFallback>
              </Avatar>
              <div>
                <DialogTitle className="text-xl font-bold text-white uppercase tracking-tight">
                  {editingPledge?.recipientName}
                </DialogTitle>
                <DialogDescription className="text-zinc-400 text-[10px] font-bold uppercase tracking-[0.2em] mt-1">
                  Update your commitment
                </DialogDescription>
              </div>
            </div>
            <button
              onClick={() => setEditingPledge(null)}
              className="absolute top-4 right-4 text-zinc-400 hover:text-white transition-colors"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          <div className="flex flex-col h-full bg-zinc-50 text-left">
            {!isPauseOpen ? (
              // --- EDIT VIEW ---
              <>
                <div className="p-6 space-y-6">
                  <div className="grid grid-cols-2 gap-5">
                    <div className="space-y-2">
                      <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                        Amount
                      </Label>
                      <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400 font-bold">
                          $
                        </span>
                        <Input
                          type="number"
                          value={editForm.amount}
                          onChange={(e) =>
                            setEditForm({
                              ...editForm,
                              amount: parseFloat(e.target.value),
                            })
                          }
                          className="pl-8 text-lg font-bold text-zinc-900 bg-white shadow-sm h-11 border-zinc-200 rounded-lg"
                        />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                        Frequency
                      </Label>
                      <Select
                        value={editForm.frequency}
                        onValueChange={(v) =>
                          setEditForm({ ...editForm, frequency: v })
                        }
                      >
                        <SelectTrigger className="bg-white shadow-sm h-11 border-zinc-200 rounded-lg text-xs font-bold uppercase">
                          <SelectValue placeholder="Select frequency" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem
                            value="Monthly"
                            className="text-xs font-bold uppercase"
                          >
                            Monthly
                          </SelectItem>
                          <SelectItem
                            value="Quarterly"
                            className="text-xs font-bold uppercase"
                          >
                            Quarterly
                          </SelectItem>
                          <SelectItem
                            value="Annually"
                            className="text-xs font-bold uppercase"
                          >
                            Annually
                          </SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  {/* Payment Method Display in Edit (Read Only / Trigger Move) */}
                  <div className="space-y-2">
                    <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                      Payment Method
                    </Label>
                    <div
                      className="bg-white border border-zinc-200 p-3 rounded-xl flex items-center justify-between cursor-pointer hover:border-zinc-300 hover:shadow-sm transition-all group"
                      onClick={() =>
                        editingPledge && handleOpenMove(editingPledge)
                      }
                    >
                      <div className="flex items-center gap-3">
                        <div className="bg-zinc-100 p-1.5 rounded-lg text-zinc-600 border border-zinc-200">
                          <CreditCard className="h-4 w-4" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-zinc-900 uppercase tracking-tight">
                            {
                              wallets.find(
                                (w) => w.id === editingPledge?.paymentMethodId,
                              )?.brand
                            }{" "}
                            ••
                            {
                              wallets.find(
                                (w) => w.id === editingPledge?.paymentMethodId,
                              )?.last4
                            }
                          </p>
                          <p className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
                            Click to change method
                          </p>
                        </div>
                      </div>
                      <ArrowRightLeft className="h-4 w-4 text-zinc-300 group-hover:text-zinc-900 transition-colors" />
                    </div>
                  </div>

                  {/* Status Control */}
                  <div className="bg-white p-4 rounded-xl border border-zinc-200 shadow-sm flex items-center justify-between">
                    <div>
                      <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900 block">
                        Pledge Status
                      </span>
                      <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-tight mt-0.5 block">
                        {editingPledge?.status === "Active"
                          ? "Currently active and processing."
                          : `Paused until ${editingPledge?.pausedUntil}`}
                      </span>
                    </div>
                    {editingPledge?.status === "Active" ? (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => setIsPauseOpen(true)}
                        className="text-amber-600 hover:bg-amber-50 hover:text-amber-700 border-amber-200 font-bold uppercase tracking-widest text-[9px] h-8 rounded-lg px-3"
                      >
                        <PauseCircle className="mr-1.5 h-3.5 w-3.5" /> Pause
                      </Button>
                    ) : (
                      <Button
                        size="sm"
                        onClick={() => handleResumePledge(editingPledge!.id)}
                        className="bg-emerald-600 text-white hover:bg-emerald-700 shadow-sm font-bold uppercase tracking-widest text-[9px] h-8 rounded-lg px-3"
                      >
                        <PlayCircle className="mr-1.5 h-3.5 w-3.5" /> Resume
                      </Button>
                    )}
                  </div>
                </div>

                <div className="p-6 bg-white border-t border-zinc-100 flex justify-between items-center">
                  <Button
                    variant="ghost"
                    className="text-red-500 hover:text-red-700 hover:bg-red-50 font-bold uppercase tracking-widest text-[9px] h-9 px-3"
                    onClick={() => handleStopPledge(editingPledge!.id)}
                  >
                    Stop Support
                  </Button>
                  <div className="flex gap-3">
                    <Button
                      variant="outline"
                      onClick={() => setEditingPledge(null)}
                      className="font-bold uppercase tracking-widest text-[9px] h-9 px-4 rounded-lg"
                    >
                      Cancel
                    </Button>
                    <Button
                      onClick={handleSaveChanges}
                      className="bg-zinc-900 text-white shadow-md font-bold uppercase tracking-widest text-[9px] h-9 px-4 rounded-lg"
                    >
                      Save Changes
                    </Button>
                  </div>
                </div>
              </>
            ) : (
              // --- PAUSE VIEW ---
              <motion.div
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                className="flex flex-col h-full"
              >
                <div className="p-6 flex-1 space-y-6">
                  <div className="flex items-center gap-2 text-amber-600 bg-amber-50 p-3 rounded-xl border border-amber-100">
                    <PauseCircle className="h-5 w-5" />
                    <span className="font-bold text-xs uppercase tracking-widest">
                      Pause Pledge
                    </span>
                  </div>

                  <div className="space-y-4">
                    <Label className="text-[10px] font-black uppercase tracking-widest text-zinc-400">
                      How long would you like to pause?
                    </Label>
                    <div className="grid grid-cols-2 gap-3">
                      {["1", "3", "6"].map((m) => (
                        <div
                          key={m}
                          onClick={() => {
                            setPauseDuration(m);
                            setCustomResumeDate("");
                          }}
                          className={cn(
                            "cursor-pointer p-4 rounded-xl border text-center transition-all hover:shadow-md",
                            pauseDuration === m && !customResumeDate
                              ? "bg-amber-50 border-amber-500 text-amber-900 font-bold ring-1 ring-amber-500 shadow-inner"
                              : "bg-white border-zinc-200 text-zinc-500 hover:border-zinc-300 font-bold uppercase tracking-widest text-[10px]",
                          )}
                        >
                          {m} Month{m !== "1" && "s"}
                        </div>
                      ))}
                      <div
                        onClick={() => {
                          setPauseDuration("");
                        }}
                        className={cn(
                          "cursor-pointer p-4 rounded-xl border text-center transition-all hover:shadow-md flex flex-col justify-center",
                          customResumeDate
                            ? "bg-amber-50 border-amber-500 text-amber-900 font-bold ring-1 ring-amber-500 shadow-inner"
                            : "bg-white border-zinc-200 text-zinc-500 hover:border-zinc-300 font-bold uppercase tracking-widest text-[10px]",
                        )}
                      >
                        <span>Specific Date</span>
                        {customResumeDate && (
                          <span className="text-[9px] mt-1">
                            {customResumeDate}
                          </span>
                        )}
                      </div>
                    </div>

                    {pauseDuration === "" && (
                      <div className="pt-2 animate-in fade-in slide-in-from-top-2">
                        <Label className="mb-2 block text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                          Resume Date
                        </Label>
                        <Input
                          type="date"
                          min={format(addMonths(new Date(), 1), "yyyy-MM-dd")}
                          onChange={(e) => setCustomResumeDate(e.target.value)}
                          className="bg-white h-11 border-zinc-200 rounded-lg font-bold"
                        />
                      </div>
                    )}

                    {!customResumeDate && (
                      <p className="text-[9px] text-zinc-400 font-bold uppercase tracking-widest text-center bg-zinc-100 p-3 rounded-lg border border-zinc-200">
                        Pledge will automatically resume on{" "}
                        <strong className="text-zinc-900">
                          {format(
                            addMonths(
                              new Date(),
                              parseInt(pauseDuration || "0"),
                            ),
                            "MMMM d, yyyy",
                          )}
                        </strong>
                        .
                      </p>
                    )}
                  </div>
                </div>

                <div className="p-6 bg-white border-t border-zinc-100 flex justify-between items-center">
                  <Button
                    variant="ghost"
                    onClick={() => setIsPauseOpen(false)}
                    className="font-bold uppercase tracking-widest text-[9px] h-9 px-4"
                  >
                    Back
                  </Button>
                  <Button
                    onClick={handlePausePledge}
                    disabled={pauseDuration === "" && !customResumeDate}
                    className="bg-amber-600 hover:bg-amber-700 text-white shadow-md font-bold uppercase tracking-widest text-[9px] h-9 px-6 rounded-lg transition-transform active:scale-95"
                  >
                    Confirm Pause
                  </Button>
                </div>
              </motion.div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      {/* --- MOVE / ADD PAYMENT DIALOG --- */}
      <Dialog
        open={!!movingPledge}
        onOpenChange={(open) => !open && setMovingPledge(null)}
      >
        <DialogContent className="sm:max-w-[550px] p-0 gap-0 overflow-hidden shadow-2xl border-none rounded-2xl max-h-[90vh] overflow-y-auto text-left">
          <div className="bg-zinc-50 p-6 border-b border-zinc-100 flex items-center justify-between sticky top-0 z-10">
            <div>
              <DialogTitle className="text-lg font-bold text-zinc-900 uppercase tracking-tight">
                {moveView === "select"
                  ? "Move Pledge"
                  : "Add New Payment Method"}
              </DialogTitle>
              <DialogDescription className="text-[10px] font-bold uppercase tracking-widest text-zinc-400 mt-1">
                {moveView === "select"
                  ? `Select a payment method for ${movingPledge?.recipientName}.`
                  : "Enter your new payment details securely."}
              </DialogDescription>
            </div>
            {moveView === "add" && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setMoveView("select")}
                className="h-8 text-[9px] font-black uppercase tracking-widest hover:bg-zinc-100 rounded-md"
              >
                <ArrowLeft className="h-3 w-3 mr-1.5" /> Back
              </Button>
            )}
          </div>

          <div className="p-6 bg-white min-h-[350px]">
            {moveView === "select" ? (
              <div className="space-y-4">
                <div className="space-y-2">
                  {wallets.map((wallet) => (
                    <div
                      key={wallet.id}
                      onClick={() => setSelectedTargetId(wallet.id)}
                      className={cn(
                        "flex items-center gap-3 p-4 rounded-xl border cursor-pointer transition-all",
                        selectedTargetId === wallet.id
                          ? "bg-zinc-50 border-zinc-900 ring-1 ring-zinc-900 shadow-sm"
                          : "bg-white border-zinc-200 hover:border-zinc-300 hover:bg-zinc-50",
                      )}
                    >
                      <div
                        className={cn(
                          "w-4 h-4 rounded-full border flex items-center justify-center shrink-0 transition-colors",
                          selectedTargetId === wallet.id
                            ? "border-zinc-900 bg-zinc-900"
                            : "border-zinc-300 bg-white",
                        )}
                      >
                        {selectedTargetId === wallet.id && (
                          <div className="w-1.5 h-1.5 rounded-full bg-white" />
                        )}
                      </div>

                      <div className="bg-white border border-zinc-200 p-1.5 rounded-lg flex items-center justify-center w-10 h-7 shadow-sm">
                        {wallet.type === "card" ? (
                          <CreditCard className="h-4 w-4 text-zinc-700" />
                        ) : (
                          <Landmark className="h-4 w-4 text-emerald-600" />
                        )}
                      </div>

                      <div className="flex-1">
                        <p className="text-sm font-bold text-zinc-900 uppercase tracking-tight">
                          {wallet.brand} ••{wallet.last4}
                        </p>
                        <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">
                          Expires 12/26
                        </p>
                      </div>
                    </div>
                  ))}
                </div>

                <Button
                  variant="outline"
                  onClick={() => setMoveView("add")}
                  className="w-full border-dashed border-zinc-300 text-zinc-400 hover:text-zinc-900 hover:border-zinc-400 hover:bg-zinc-50 transition-all h-12 rounded-xl font-bold uppercase tracking-widest text-[10px]"
                >
                  <Plus className="h-4 w-4 mr-2" /> Add New Payment Method
                </Button>
              </div>
            ) : (
              <div className="space-y-6 animate-in slide-in-from-right-4 fade-in duration-300">
                {/* Type Selector */}
                <div className="flex p-1 bg-zinc-100 rounded-xl border border-zinc-200 shadow-inner">
                  <button
                    onClick={() => setNewMethodType("card")}
                    className={cn(
                      "flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all flex items-center justify-center gap-2",
                      newMethodType === "card"
                        ? "bg-white text-zinc-900 shadow-md"
                        : "text-zinc-400 hover:text-zinc-600",
                    )}
                  >
                    <CreditCard className="h-3.5 w-3.5" /> Credit Card
                  </button>
                  <button
                    onClick={() => setNewMethodType("bank")}
                    className={cn(
                      "flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all flex items-center justify-center gap-2",
                      newMethodType === "bank"
                        ? "bg-white text-zinc-900 shadow-md"
                        : "text-zinc-400 hover:text-zinc-600",
                    )}
                  >
                    <Landmark className="h-3.5 w-3.5" /> Bank Account
                  </button>
                </div>

                {newMethodType === "card" ? (
                  /* CREDIT CARD FORM */
                  <div className="space-y-5">
                    <div className="space-y-2 text-left">
                      <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                        Card Number
                      </Label>
                      <div className="relative">
                        <CreditCard className="absolute left-3 top-3.5 h-4 w-4 text-zinc-400" />
                        <Input
                          placeholder="0000 0000 0000 0000"
                          className="pl-9 h-11 bg-zinc-50 border-zinc-200 focus:bg-white transition-all font-mono rounded-lg"
                          value={newCard.number}
                          onChange={(e) =>
                            setNewCard({ ...newCard, number: e.target.value })
                          }
                        />
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2 text-left">
                        <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                          Expiry
                        </Label>
                        <Input
                          placeholder="MM/YY"
                          className="h-11 bg-zinc-50 border-zinc-200 focus:bg-white text-center font-mono rounded-lg"
                          value={newCard.expiry}
                          onChange={(e) =>
                            setNewCard({ ...newCard, expiry: e.target.value })
                          }
                        />
                      </div>
                      <div className="space-y-2 text-left">
                        <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                          CVC
                        </Label>
                        <div className="relative">
                          <Lock className="absolute left-3 top-3.5 h-3.5 w-3.5 text-zinc-400" />
                          <Input
                            placeholder="123"
                            className="pl-8 h-11 bg-zinc-50 border-zinc-200 focus:bg-white text-center font-mono rounded-lg"
                            value={newCard.cvc}
                            onChange={(e) =>
                              setNewCard({ ...newCard, cvc: e.target.value })
                            }
                          />
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  /* BANK ACCOUNT FORM */
                  <div className="space-y-5">
                    <div className="space-y-2 text-left">
                      <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                        Account Holder Name
                      </Label>
                      <Input
                        placeholder="Full Name on Account"
                        className="h-11 bg-zinc-50 border-zinc-200 focus:bg-white rounded-lg font-bold uppercase tracking-tight"
                        value={newBank.holderName}
                        onChange={(e) =>
                          setNewBank({ ...newBank, holderName: e.target.value })
                        }
                      />
                    </div>
                    <div className="space-y-2 text-left">
                      <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                        Routing Number
                      </Label>
                      <div className="relative">
                        <Landmark className="absolute left-3 top-3.5 h-4 w-4 text-zinc-400" />
                        <Input
                          placeholder="9 Digit Routing"
                          className="pl-9 h-11 bg-zinc-50 border-zinc-200 focus:bg-white transition-all font-mono rounded-lg"
                          value={newBank.routing}
                          onChange={(e) =>
                            setNewBank({ ...newBank, routing: e.target.value })
                          }
                        />
                      </div>
                    </div>
                    <div className="space-y-2 text-left">
                      <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400">
                        Account Number
                      </Label>
                      <Input
                        placeholder="Account Number"
                        className="h-11 bg-zinc-50 border-zinc-200 focus:bg-white font-mono rounded-lg"
                        value={newBank.account}
                        onChange={(e) =>
                          setNewBank({ ...newBank, account: e.target.value })
                        }
                      />
                    </div>
                    <div className="bg-zinc-100 text-zinc-600 text-[10px] font-bold uppercase tracking-widest p-4 rounded-xl border border-zinc-200">
                      <p className="leading-relaxed">
                        By providing your bank information, you authorize Give
                        Hope to debit your account for this pledge.
                      </p>
                    </div>
                  </div>
                )}

                <Separator />

                {/* Billing Address Section */}
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <Label className="text-[9px] font-black uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2">
                      <MapPin className="h-3 w-3" /> Billing Address
                    </Label>
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
                        Use profile address?
                      </span>
                      <Switch
                        checked={useProfileAddress}
                        onCheckedChange={setUseProfileAddress}
                        className="data-[state=checked]:bg-zinc-900"
                      />
                    </div>
                  </div>

                  {useProfileAddress ? (
                    <div className="p-4 bg-zinc-50 rounded-xl border border-zinc-200 text-[10px] font-bold uppercase tracking-widest text-zinc-500 flex items-start gap-2 shadow-inner">
                      <Check className="h-4 w-4 text-emerald-500 mt-0.5" />
                      <span className="leading-relaxed">{profileAddress}</span>
                    </div>
                  ) : (
                    <div className="space-y-3 animate-in slide-in-from-top-2 fade-in">
                      <Input
                        placeholder="Street Address"
                        className="h-10 bg-zinc-50 border-zinc-200 focus:bg-white rounded-lg text-xs font-bold uppercase tracking-tight"
                        value={billingAddress.street}
                        onChange={(e) =>
                          setBillingAddress({
                            ...billingAddress,
                            street: e.target.value,
                          })
                        }
                      />
                      <div className="grid grid-cols-2 gap-3">
                        <Input
                          placeholder="City"
                          className="h-10 bg-zinc-50 border-zinc-200 focus:bg-white rounded-lg text-xs font-bold uppercase tracking-tight"
                          value={billingAddress.city}
                          onChange={(e) =>
                            setBillingAddress({
                              ...billingAddress,
                              city: e.target.value,
                            })
                          }
                        />
                        <Input
                          placeholder="State"
                          className="h-10 bg-zinc-50 border-zinc-200 focus:bg-white rounded-lg text-xs font-bold uppercase tracking-tight"
                          value={billingAddress.state}
                          onChange={(e) =>
                            setBillingAddress({
                              ...billingAddress,
                              state: e.target.value,
                            })
                          }
                        />
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        <Input
                          placeholder="Zip Code"
                          className="h-10 bg-zinc-50 border-zinc-200 focus:bg-white rounded-lg text-xs font-bold uppercase tracking-tight"
                          value={billingAddress.zip}
                          onChange={(e) =>
                            setBillingAddress({
                              ...billingAddress,
                              zip: e.target.value,
                            })
                          }
                        />
                        <Select
                          value={billingAddress.country}
                          onValueChange={(v) =>
                            setBillingAddress({ ...billingAddress, country: v })
                          }
                        >
                          <SelectTrigger className="h-10 bg-zinc-50 border-zinc-200 focus:bg-white rounded-lg text-[10px] font-black uppercase tracking-widest">
                            <SelectValue placeholder="Country" />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem
                              value="USA"
                              className="text-[10px] font-bold uppercase tracking-widest"
                            >
                              USA
                            </SelectItem>
                            <SelectItem
                              value="CAN"
                              className="text-[10px] font-bold uppercase tracking-widest"
                            >
                              Canada
                            </SelectItem>
                            <SelectItem
                              value="UK"
                              className="text-[10px] font-bold uppercase tracking-widest"
                            >
                              UK
                            </SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-zinc-300 pt-2 pb-2">
                  <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" />{" "}
                  Securely encrypted by Stripe
                </div>
              </div>
            )}
          </div>

          <div className="p-6 bg-zinc-50 border-t border-zinc-100 flex justify-between items-center sticky bottom-0 z-10">
            <Button
              variant="ghost"
              onClick={() => setMovingPledge(null)}
              className="font-bold uppercase tracking-widest text-[9px] h-10 px-4 rounded-lg"
            >
              Cancel
            </Button>
            {moveView === "select" ? (
              <Button
                onClick={handleConfirmMove}
                disabled={!selectedTargetId}
                className="bg-zinc-900 text-white shadow-lg font-bold uppercase tracking-widest text-[9px] h-10 px-6 rounded-lg transition-transform active:scale-95"
              >
                Confirm Move
              </Button>
            ) : (
              <Button
                onClick={handleSaveNewMethod}
                className="bg-zinc-900 text-white shadow-lg font-bold uppercase tracking-widest text-[9px] h-10 px-6 rounded-lg transition-transform active:scale-95"
              >
                Save & Use {newMethodType === "card" ? "Card" : "Account"}
              </Button>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@asym/ui/components/shadcn/avatar";
import { Badge } from "@asym/ui/components/shadcn/badge";
import { Button } from "@asym/ui/components/shadcn/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
  CardFooter,
} from "@asym/ui/components/shadcn/card";
import { ImageUpload } from "@asym/ui/components/shadcn/image-upload";
import { Input } from "@asym/ui/components/shadcn/input";
import { Label } from "@asym/ui/components/shadcn/label";
import { ScrollArea } from "@asym/ui/components/shadcn/scroll-area";
import { Switch } from "@asym/ui/components/shadcn/switch";
import { cn } from "@asym/ui/lib/utils";
import {
  User,
  Bell,
  Shield,
  Mail,
  Phone,
  MapPin,
  Camera,
  Check,
  Loader2,
  Lock,
  ChevronRight,
  Eye,
  EyeOff,
  Laptop,
  History,
  Receipt,
  Heart,
  Globe,
  AlertTriangle,
} from "lucide-react";
import { motion, AnimatePresence } from "motion/react";
import React, { useState } from "react";

// --- Types ---
type TabId = "profile" | "notifications" | "security";

interface SettingTab {
  id: TabId;
  label: string;
  icon: React.ElementType;
}

const TABS: SettingTab[] = [
  { id: "profile", label: "My Profile", icon: User },
  { id: "notifications", label: "Notifications", icon: Bell },
  { id: "security", label: "Security", icon: Shield },
];

// --- Helper Components ---

const PasswordInput = ({
  id,
  label,
  value,
  onChange,
  placeholder,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  placeholder?: string;
}) => {
  const [isVisible, setIsVisible] = useState(false);

  return (
    <div className="space-y-2">
      <Label htmlFor={id} className="text-zinc-700 font-medium">
        {label}
      </Label>
      <div className="relative group">
        <Input
          id={id}
          type={isVisible ? "text" : "password"}
          value={value}
          onChange={onChange}
          className="pr-10 bg-zinc-50 border-zinc-200 focus:bg-white focus:ring-2 focus:ring-zinc-100 transition-all duration-200"
          placeholder={placeholder}
        />
        <button
          type="button"
          onClick={() => setIsVisible(!isVisible)}
          className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-zinc-600 transition-colors focus:outline-none"
        >
          {isVisible ? (
            <EyeOff className="h-4 w-4" />
          ) : (
            <Eye className="h-4 w-4" />
          )}
        </button>
      </div>
    </div>
  );
};

// --- Tabs ---

const ProfileTab = () => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [avatarUrl, setAvatarUrl] = useState(
    "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?fit=facearea&facepad=2&w=256&h=256&q=80",
  );

  const handleSave = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2000);
    }, 1500);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="space-y-6"
    >
      {/* Avatar Section */}
      <Card className="border-zinc-200 shadow-sm overflow-hidden text-left rounded-xl">
        <CardHeader className="bg-zinc-50/50 border-b border-zinc-100 pb-4">
          <CardTitle className="text-lg">Public Avatar</CardTitle>
          <CardDescription>
            Displayed on your profile and interactions.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-6">
          <div className="flex flex-col sm:flex-row items-center gap-6">
            <ImageUpload
              value={avatarUrl}
              onChange={(url) => setAvatarUrl(url)}
              path="avatars"
              aspect={1}
            >
              <div className="relative group cursor-pointer">
                <Avatar className="h-20 w-20 border-4 border-white shadow-md ring-1 ring-zinc-100">
                  <AvatarImage src={avatarUrl} />
                  <AvatarFallback className="bg-zinc-900 text-white text-2xl uppercase font-bold">
                    JD
                  </AvatarFallback>
                </Avatar>
                <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                  <Camera className="text-white h-6 w-6" />
                </div>
              </div>
            </ImageUpload>
            <div className="flex flex-col gap-3 text-center sm:text-left">
              <div>
                <h4 className="font-bold text-zinc-900 uppercase tracking-tight">
                  Profile Photo
                </h4>
                <p className="text-[10px] font-bold text-zinc-400 mt-1 uppercase tracking-widest">
                  JPG, GIF or PNG. Large files auto-optimized.
                </p>
              </div>
              <div className="flex gap-3 justify-center sm:justify-start">
                <ImageUpload
                  value={avatarUrl}
                  onChange={(url) => setAvatarUrl(url)}
                  path="avatars"
                >
                  <Button
                    variant="outline"
                    size="sm"
                    className="bg-white h-8 text-[10px] font-black uppercase tracking-widest border-zinc-200 shadow-sm hover:bg-zinc-50 rounded-lg px-4"
                  >
                    Upload New
                  </Button>
                </ImageUpload>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setAvatarUrl("")}
                  className="text-rose-600 h-8 text-[10px] font-black uppercase tracking-widest hover:text-rose-700 hover:bg-rose-50 rounded-lg px-4"
                >
                  Remove
                </Button>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Personal Info Form */}
      <Card className="border-zinc-200 shadow-sm text-left rounded-xl">
        <CardHeader className="bg-zinc-50/50 border-b border-zinc-100 pb-4">
          <CardTitle className="text-lg uppercase font-bold tracking-tight">
            Personal Information
          </CardTitle>
          <CardDescription className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
            Update your identity and contact details.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div className="space-y-2">
              <Label
                htmlFor="firstName"
                className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
              >
                First Name
              </Label>
              <Input
                id="firstName"
                defaultValue="John"
                className="bg-white border-zinc-200 focus:border-zinc-900 transition-all h-10 rounded-lg"
              />
            </div>
            <div className="space-y-2">
              <Label
                htmlFor="lastName"
                className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
              >
                Last Name
              </Label>
              <Input
                id="lastName"
                defaultValue="Doe"
                className="bg-white border-zinc-200 focus:border-zinc-900 transition-all h-10 rounded-lg"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div className="space-y-2">
              <Label
                htmlFor="email"
                className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
              >
                Email Address
              </Label>
              <div className="relative">
                <Mail className="absolute left-3 top-3 h-4 w-4 text-zinc-400" />
                <Input
                  id="email"
                  type="email"
                  defaultValue="john.doe@example.com"
                  className="pl-9 bg-white border-zinc-200 focus:border-zinc-900 transition-all h-10 rounded-lg"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label
                htmlFor="phone"
                className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
              >
                Phone Number
              </Label>
              <div className="relative">
                <Phone className="absolute left-3 top-3 h-4 w-4 text-zinc-400" />
                <Input
                  id="phone"
                  type="tel"
                  defaultValue="+1 (555) 123-4567"
                  className="pl-9 bg-white border-zinc-200 focus:border-zinc-900 transition-all h-10 rounded-lg"
                />
              </div>
            </div>
          </div>

          <div className="space-y-4 pt-2">
            <div className="space-y-2">
              <Label
                htmlFor="address"
                className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
              >
                Street Address
              </Label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3 h-4 w-4 text-zinc-400" />
                <Input
                  id="address"
                  defaultValue="123 Mission Way"
                  className="pl-9 bg-white border-zinc-200 focus:border-zinc-900 transition-all h-10 rounded-lg"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-5">
              <div className="space-y-2">
                <Label
                  htmlFor="city"
                  className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
                >
                  City
                </Label>
                <Input
                  id="city"
                  defaultValue="San Francisco"
                  className="bg-white border-zinc-200 h-10 rounded-lg"
                />
              </div>
              <div className="space-y-2">
                <Label
                  htmlFor="state"
                  className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
                >
                  State
                </Label>
                <Input
                  id="state"
                  defaultValue="CA"
                  className="bg-white border-zinc-200 h-10 rounded-lg"
                />
              </div>
              <div className="space-y-2 col-span-2 md:col-span-1">
                <Label
                  htmlFor="zip"
                  className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400"
                >
                  Postal Code
                </Label>
                <Input
                  id="zip"
                  defaultValue="94105"
                  className="bg-white border-zinc-200 h-10 rounded-lg"
                />
              </div>
            </div>
          </div>
        </CardContent>
        <CardFooter className="bg-zinc-50/50 border-t border-zinc-100 p-4 flex flex-col-reverse sm:flex-row justify-between items-center gap-4">
          <p className="text-[10px] font-bold uppercase tracking-widest text-zinc-400 hidden sm:block">
            Last updated: 3 days ago
          </p>
          <div className="flex gap-3 w-full sm:w-auto">
            <Button
              variant="ghost"
              className="text-zinc-500 hover:text-zinc-900 w-full sm:w-auto h-9 text-[10px] font-bold uppercase tracking-widest"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={loading}
              className={cn(
                "min-w-[120px] transition-all w-full sm:w-auto h-9 text-[10px] font-black uppercase tracking-widest rounded-lg px-6",
                success
                  ? "bg-emerald-600 hover:bg-emerald-700"
                  : "bg-zinc-900 hover:bg-zinc-800",
              )}
            >
              {loading ? (
                <Loader2 className="mr-2 h-3 w-3 animate-spin" />
              ) : success ? (
                <Check className="mr-2 h-3 w-3" />
              ) : null}
              {loading ? "Saving..." : success ? "Saved" : "Save Changes"}
            </Button>
          </div>
        </CardFooter>
      </Card>
    </motion.div>
  );
};

const NotificationsTab = () => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  const [preferences, setPreferences] = useState({
    receipts: true,
    monthlyStatement: true,
    fieldUpdates: true,
    videoStories: true,
    newsletters: false,
    emergencyAppeals: true,
    smsAlerts: false,
  });

  const handleToggle = (key: keyof typeof preferences) => {
    setPreferences((prev) => ({ ...prev, [key]: !prev[key] }));
    if (success) setSuccess(false);
  };

  const handleSave = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2500);
    }, 1200);
  };

  const categories = [
    {
      title: "Billing & Receipts",
      icon: Receipt,
      color: "text-blue-600 bg-blue-50",
      items: [
        {
          key: "receipts",
          label: "Instant Donation Receipts",
          desc: "Email receipt after every donation.",
        },
        {
          key: "monthlyStatement",
          label: "Monthly Statements",
          desc: "Consolidated summary sent on the 1st.",
        },
      ],
    },
    {
      title: "Impact Updates",
      icon: Heart,
      color: "text-rose-600 bg-rose-50",
      items: [
        {
          key: "fieldUpdates",
          label: "Field Partner Updates",
          desc: "Stories directly from the workers you support.",
          recommended: true,
        },
        {
          key: "videoStories",
          label: "Video Stories",
          desc: "Links to video messages and reports.",
        },
      ],
    },
    {
      title: "Organization",
      icon: Globe,
      color: "text-emerald-600 bg-emerald-50",
      items: [
        {
          key: "newsletters",
          label: "Quarterly Newsletter",
          desc: "High-level vision and stats.",
        },
        {
          key: "emergencyAppeals",
          label: "Emergency Appeals",
          desc: "Notifications about urgent crises.",
        },
      ],
    },
  ];

  return (
    <Card className="border-zinc-200 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500 text-left rounded-xl">
      <CardHeader className="bg-zinc-50/50 border-b border-zinc-100 pb-4">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <CardTitle className="text-lg uppercase font-bold tracking-tight">
              Notification Preferences
            </CardTitle>
            <CardDescription className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
              Customize how you want to hear from us.
            </CardDescription>
          </div>
        </div>
      </CardHeader>

      <CardContent className="p-0">
        <div className="divide-y divide-zinc-100">
          {categories.map((category, idx) => (
            <div
              key={idx}
              className="p-6 md:p-8 hover:bg-zinc-50/30 transition-colors"
            >
              <div className="flex flex-col md:flex-row md:gap-12 gap-6">
                <div className="md:w-48 shrink-0 flex items-start gap-3">
                  <div
                    className={cn("p-2 rounded-lg shrink-0", category.color)}
                  >
                    <category.icon className="h-4 w-4" />
                  </div>
                  <h3 className="text-xs font-black uppercase tracking-widest text-zinc-900 mt-1.5">
                    {category.title}
                  </h3>
                </div>

                <div className="flex-1 space-y-6">
                  {category.items.map((item: any) => (
                    <div
                      key={item.key}
                      className="flex items-start justify-between gap-4"
                    >
                      <div className="space-y-0.5">
                        <div className="flex items-center gap-2 text-left">
                          <Label
                            htmlFor={item.key}
                            className="text-sm font-bold text-zinc-900 cursor-pointer uppercase tracking-tight"
                          >
                            {item.label}
                          </Label>
                          {item.recommended && (
                            <Badge
                              variant="secondary"
                              className="bg-zinc-100 text-zinc-900 border-zinc-200 text-[8px] h-4 px-1.5 font-black uppercase tracking-widest"
                            >
                              Recommended
                            </Badge>
                          )}
                        </div>
                        <p className="text-[10px] font-bold uppercase tracking-tight text-zinc-400 leading-relaxed max-w-md">
                          {item.desc}
                        </p>
                      </div>
                      <Switch
                        id={item.key}
                        checked={(preferences as any)[item.key]}
                        onCheckedChange={() => handleToggle(item.key as any)}
                        className="data-[state=checked]:bg-zinc-900 mt-1"
                      />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      </CardContent>

      <CardFooter className="bg-zinc-50/50 border-t border-zinc-100 p-4 flex flex-col sm:flex-row justify-between items-center gap-4">
        <p className="text-[9px] font-black uppercase tracking-widest text-zinc-400 italic flex items-center gap-2 text-center sm:text-left">
          <AlertTriangle className="h-3 w-3 text-amber-500" />
          System alerts cannot be disabled.
        </p>
        <Button
          onClick={handleSave}
          disabled={loading || success}
          className={cn(
            "min-w-[140px] shadow-sm transition-all duration-300 font-black h-9 w-full sm:w-auto text-[10px] uppercase tracking-widest rounded-lg px-6",
            success
              ? "bg-emerald-600 hover:bg-emerald-700"
              : "bg-zinc-900 hover:bg-zinc-800",
          )}
        >
          {loading ? (
            <Loader2 className="mr-2 h-3 w-3 animate-spin" />
          ) : success ? (
            <Check className="mr-2 h-3 w-3" />
          ) : null}
          {loading
            ? "Saving..."
            : success
              ? "Changes Saved"
              : "Save Preferences"}
        </Button>
      </CardFooter>
    </Card>
  );
};

const SecurityTab = () => {
  const [passwords, setPasswords] = useState({
    current: "",
    new: "",
    confirm: "",
  });
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Password Strength Logic
  const getStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 8) score++;
    if (/[0-9]/.test(pass)) score++;
    if (/[!@#$%^&*]/.test(pass)) score++;
    if (/[A-Z]/.test(pass)) score++;
    return score;
  };

  const strengthScore = getStrength(passwords.new);
  const strengthColor =
    strengthScore < 2
      ? "bg-rose-500"
      : strengthScore < 4
        ? "bg-amber-500"
        : "bg-emerald-500";
  const widthPercent = Math.min((strengthScore / 4) * 100, 100);

  const handleUpdate = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2000);
      setPasswords({ current: "", new: "", confirm: "" });
    }, 1500);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="space-y-6 max-w-4xl text-left"
    >
      {/* 1. Login & Password Card */}
      <Card className="border-zinc-200 shadow-sm overflow-hidden rounded-xl">
        <CardHeader className="bg-zinc-50/50 border-b border-zinc-100 pb-4 text-left">
          <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
            <div className="space-y-1">
              <CardTitle className="text-lg flex items-center gap-2 font-bold uppercase tracking-tight">
                <Lock className="h-4 w-4 text-zinc-400" /> Login & Password
              </CardTitle>
              <CardDescription className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
                Manage your password to keep your account secure.
              </CardDescription>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-6 md:p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
            {/* Left Col: Current Password */}
            <div className="space-y-6">
              <PasswordInput
                id="current"
                label="Current Password"
                value={passwords.current}
                onChange={(e) =>
                  setPasswords({ ...passwords, current: e.target.value })
                }
                placeholder="Enter current password"
              />

              <div className="bg-zinc-50 rounded-xl p-4 border border-zinc-100 shadow-inner">
                <div className="flex gap-3">
                  <div className="p-1.5 bg-white rounded-lg shadow-sm text-zinc-900 border border-zinc-100 h-fit">
                    <History className="h-3.5 w-3.5" />
                  </div>
                  <div className="space-y-1">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-zinc-900">
                      Forgot your password?
                    </h4>
                    <Button
                      variant="link"
                      className="text-zinc-500 font-bold p-0 h-auto text-[10px] uppercase tracking-widest hover:text-zinc-900"
                    >
                      Reset via Email
                    </Button>
                  </div>
                </div>
              </div>
            </div>

            {/* Right Col: New Password */}
            <div className="space-y-5">
              <PasswordInput
                id="new"
                label="New Password"
                value={passwords.new}
                onChange={(e) =>
                  setPasswords({ ...passwords, new: e.target.value })
                }
                placeholder="Enter new password"
              />

              {/* Strength Meter */}
              <div className="space-y-1.5">
                <div className="h-1 w-full bg-zinc-100 rounded-full overflow-hidden">
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${widthPercent}%` }}
                    className={cn(
                      "h-full transition-colors duration-500 ease-out",
                      strengthColor,
                    )}
                  />
                </div>
                <div className="flex justify-between">
                  <span className="text-[9px] font-black uppercase tracking-widest text-zinc-300">
                    Strength
                  </span>
                  <span className="text-[9px] font-black uppercase tracking-widest text-zinc-500">
                    {strengthScore >= 4
                      ? "Strong"
                      : strengthScore >= 2
                        ? "Medium"
                        : "Weak"}
                  </span>
                </div>
              </div>

              <PasswordInput
                id="confirm"
                label="Confirm New Password"
                value={passwords.confirm}
                onChange={(e) =>
                  setPasswords({ ...passwords, confirm: e.target.value })
                }
                placeholder="Confirm new password"
              />
            </div>
          </div>
        </CardContent>
        <CardFooter className="bg-zinc-50/50 border-t border-zinc-100 p-4 flex justify-end">
          <Button
            onClick={handleUpdate}
            disabled={
              loading ||
              strengthScore < 3 ||
              passwords.new !== passwords.confirm
            }
            className={cn(
              "min-w-[140px] h-9 shadow-sm transition-all w-full sm:w-auto text-[10px] font-black uppercase tracking-widest rounded-lg px-6",
              success
                ? "bg-emerald-600 hover:bg-emerald-700"
                : "bg-zinc-900 hover:bg-zinc-800",
            )}
          >
            {loading ? (
              <Loader2 className="mr-2 h-3 w-3 animate-spin" />
            ) : success ? (
              <Check className="mr-2 h-3 w-3" />
            ) : null}
            {loading
              ? "Updating..."
              : success
                ? "Password Updated"
                : "Update Password"}
          </Button>
        </CardFooter>
      </Card>

      {/* 2. Additional Security */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card className="border-zinc-200 shadow-sm flex flex-col rounded-xl text-left">
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2 font-bold uppercase tracking-tight">
              <Shield className="h-4 w-4 text-emerald-600" /> Two-Factor Auth
            </CardTitle>
          </CardHeader>
          <CardContent className="flex-1">
            <p className="text-[10px] font-bold uppercase tracking-tight text-zinc-500 leading-relaxed mb-4">
              Secure your account by requiring a verification code when signing
              in.
            </p>
            <div className="flex items-center justify-between p-3 rounded-xl bg-zinc-50 border border-zinc-100 shadow-inner">
              <span className="text-[10px] font-black uppercase tracking-widest text-zinc-900">
                Status
              </span>
              <Badge
                variant="outline"
                className="text-[9px] font-black uppercase tracking-widest text-zinc-400 border-zinc-200"
              >
                Disabled
              </Badge>
            </div>
          </CardContent>
          <CardFooter className="pt-0 pb-4">
            <Button
              variant="outline"
              className="w-full text-[10px] font-black uppercase tracking-widest h-9 rounded-lg border-zinc-200 hover:bg-zinc-50 transition-all"
            >
              Configure 2FA
            </Button>
          </CardFooter>
        </Card>

        <Card className="border-zinc-200 shadow-sm flex flex-col rounded-xl text-left">
          <CardHeader className="pb-3">
            <CardTitle className="text-base flex items-center gap-2 font-bold uppercase tracking-tight">
              <Laptop className="h-4 w-4 text-blue-600" /> Active Sessions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4 flex-1">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-zinc-100 rounded-lg text-zinc-500 border border-zinc-200">
                <Laptop className="h-4 w-4" />
              </div>
              <div className="flex-1">
                <p className="text-sm font-bold text-zinc-900 uppercase tracking-tight">
                  Macbook Pro
                </p>
                <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest">
                  San Francisco • Active now
                </p>
              </div>
              <div className="h-2 w-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
            </div>
          </CardContent>
          <CardFooter className="pt-0 pb-4">
            <Button
              variant="ghost"
              className="w-full text-[10px] font-black uppercase tracking-widest h-9 text-rose-600 hover:text-rose-700 hover:bg-rose-50 rounded-lg"
            >
              Sign out other devices
            </Button>
          </CardFooter>
        </Card>
      </div>
    </motion.div>
  );
};

export default function DonorSettingsPage() {
  const [activeTab, setActiveTab] = useState<TabId>("profile");

  return (
    <div className="max-w-5xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20 pt-4">
      {/* Header */}
      <div className="space-y-1.5 px-1 text-left">
        <h1 className="text-3xl font-bold text-zinc-900 tracking-tight uppercase">
          Settings
        </h1>
        <p className="text-zinc-500 text-lg font-bold uppercase tracking-widest text-[10px]">
          Manage your profile and preferences.
        </p>
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        {/* Responsive Sidebar Nav */}
        <div className="w-full lg:w-64 shrink-0 lg:sticky lg:top-24 h-fit z-10">
          <ScrollArea className="w-full whitespace-nowrap lg:whitespace-normal">
            <div className="flex lg:flex-col gap-2 p-1 bg-white rounded-xl border border-zinc-200 shadow-sm">
              {TABS.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={cn(
                    "flex items-center gap-3 px-4 py-3 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all duration-200 relative overflow-hidden group min-w-[140px] lg:w-full",
                    activeTab === tab.id
                      ? "bg-zinc-900 text-white shadow-md shadow-zinc-200"
                      : "text-zinc-500 hover:bg-zinc-50 hover:text-zinc-900",
                  )}
                >
                  <tab.icon
                    className={cn(
                      "h-4 w-4 relative z-10",
                      activeTab === tab.id
                        ? "text-white"
                        : "text-zinc-400 group-hover:text-zinc-600",
                    )}
                  />
                  <span className="relative z-10">{tab.label}</span>
                  {activeTab === tab.id && (
                    <ChevronRight className="h-3 w-3 ml-auto opacity-50 hidden lg:block relative z-10" />
                  )}
                </button>
              ))}
            </div>
          </ScrollArea>
        </div>

        {/* Content Area */}
        <div className="flex-1 min-w-0">
          <AnimatePresence mode="wait">
            <motion.div
              key={activeTab}
              initial={{ opacity: 0, x: 10 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -10 }}
              transition={{ duration: 0.2 }}
            >
              {activeTab === "profile" && <ProfileTab />}
              {activeTab === "notifications" && <NotificationsTab />}
              {activeTab === "security" && <SecurityTab />}
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}

